"""Offline payload compilation, client replay and origin evidence audit.

Reads exactly one UTF-8 JSON document on stdin and writes exactly one JSON
object on stdout.  Anything the contract rejects becomes ``{"error":"input"}``
with exit status 0.
"""
import gc
import json
import math
import os
import re
import sys
import traceback
from pathlib import Path

# The local no-Docker worker stages the same pinned wheels here. In the public
# image the packages are installed normally and this directory is unnecessary.
if Path('/opt/h3deps').is_dir():
    sys.path.insert(0, '/opt/h3deps')

sys.setrecursionlimit(20000)

from schema import compile_cases                                     # noqa: E402
from modules.byte_program import MAX, Context, ExpressionError       # noqa: E402
from modules.capture_audit import (TOKEN, BudgetError, audit_channels,  # noqa: E402
                                   case_flags)
from modules.events import ExternalEvent                             # noqa: E402
from modules.fuzz_adapter import FuzzExecutor                        # noqa: E402

NAME = re.compile(r'[A-Za-z0-9_.-]{1,32}\Z', re.ASCII)
SEED_CHARS = frozenset(
    'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_.-')
ROOT_KEYS = ('seed', 'definitions', 'timeout_ms', 'cases', 'events', 'channels')
EXPECT_KEYS = ('method', 'target', 'host')
HEADER_KEYS = ('Type', 'headers_kv', 'data_to_transfered', 'End_Stream')
DATA_KEYS = ('Type', 'data_to_transfered', 'End_Stream')
SLEEP_KEYS = ('Type', 'Time_to_Stop')

MAX_STDIN = 8 * 1024 ** 2
MAX_DEFINITIONS = 8192
MAX_CASES = 2000
MAX_CHANNELS = 256
MAX_ITEMS = 50000
MAX_PAIRS = 32768
MAX_BLOCK_PAIRS = 128
MAX_EXPRESSION = 8192
MAX_TEMPLATE = 65536
MAX_STREAM = (1 << 32) - 1


class InputError(ValueError):
    """The document violates the published input domain."""


def exact(obj, keys):
    if type(obj) is not dict or set(obj) != set(keys):
        raise InputError('object keys')


def integer(value, minimum=0, maximum=MAX):
    if type(value) is not int or not minimum <= value <= maximum:
        raise InputError('integer')
    return value


def sequence(value, maximum):
    if type(value) is not list or len(value) > maximum:
        raise InputError('array')
    return value


def text(value, maximum=MAX_TEMPLATE):
    if type(value) is not str or len(value) > maximum:
        raise InputError('string')
    value.encode('utf8')
    return value


def name(value):
    label = text(value, 32)
    if not NAME.fullmatch(label):
        raise InputError('name')
    return label


def pairs(items):
    out = {}
    for key, value in items:
        if key in out:
            raise InputError('duplicate key')
        out[key] = value
    return out


def bad_constant(value):
    raise InputError('nonfinite JSON')


def finite_float(value):
    result = float(value)
    if not math.isfinite(result):
        raise InputError('nonfinite JSON')
    return result


def visible(value, limit=8192):
    label = text(value, limit)
    raw = label.encode('ascii')
    if not raw or any(byte < 0x21 or byte > 0x7e for byte in raw):
        raise InputError('expected identity')
    return label


class Budgets:
    __slots__ = ('items', 'pairs')

    def __init__(self):
        self.items = 0
        self.pairs = 0

    def take_items(self, count):
        self.items += count
        if self.items > MAX_ITEMS:
            raise InputError('combined item budget')

    def take_pairs(self, count):
        self.pairs += count
        if self.pairs > MAX_PAIRS:
            raise InputError('combined header pair budget')


def compile_expect(raw):
    exact(raw, EXPECT_KEYS)
    out = {}
    for key in EXPECT_KEYS:
        out[key] = visible(raw[key])
    if not TOKEN.fullmatch(out['method'].encode('ascii')):
        raise InputError('expected method token')
    return out


def compile_frame(raw, context, coordinate, budgets):
    """Validate one fuzz frame and compile its templates."""
    if type(raw) is not dict:
        raise InputError('frame')
    kind = raw.get('Type')
    if type(kind) is not str:
        raise InputError('frame type')
    keys = set(raw)
    if kind == 'headers':
        if not keys <= set(HEADER_KEYS):
            raise InputError('header frame keys')
        has_map = 'headers_kv' in keys
        has_list = 'data_to_transfered' in keys
        if has_map == has_list:
            raise InputError('header representation')
        end = raw.get('End_Stream', False)
        if type(end) is not bool:
            raise InputError('End_Stream')
        if has_map:
            block = raw['headers_kv']
            if type(block) is not dict or len(block) > MAX_BLOCK_PAIRS:
                raise InputError('header mapping')
            source = list(block.items())
        else:
            block = raw['data_to_transfered']
            if type(block) is not list or len(block) > MAX_BLOCK_PAIRS:
                raise InputError('header list')
            source = []
            for pair in block:
                if type(pair) is not list or len(pair) != 2:
                    raise InputError('header pair')
                source.append((pair[0], pair[1]))
        budgets.take_pairs(len(source))
        for index, (key, value) in enumerate(source):
            key = text(key)
            value = text(value)
            context.template(key, '%s/h/%d/n' % (coordinate, index))
            context.template(value, '%s/h/%d/v' % (coordinate, index))
    elif kind in ('data', 'datagram'):
        if not keys <= set(DATA_KEYS) or 'data_to_transfered' not in keys:
            raise InputError('data frame keys')
        end = raw.get('End_Stream', True)
        if type(end) is not bool:
            raise InputError('End_Stream')
        context.template(text(raw['data_to_transfered']), '%s/data' % coordinate)
    elif kind == 'sleep':
        if keys != set(SLEEP_KEYS):
            raise InputError('sleep frame keys')
        integer(raw['Time_to_Stop'])
    else:
        raise InputError('frame type')


class Compiled:
    __slots__ = ('context', 'timeout', 'cases', 'events', 'channels')

    def __init__(self, context, timeout, cases, events, channels):
        self.context = context
        self.timeout = timeout
        self.cases = cases
        self.events = events
        self.channels = channels


def compile_document(document):
    exact(document, ROOT_KEYS)
    seed = text(document['seed'], 64)
    if any(char not in SEED_CHARS for char in seed):
        raise InputError('seed')
    raw_definitions = sequence(document['definitions'], MAX_DEFINITIONS)
    definitions = []
    for row in raw_definitions:
        if type(row) is not list or len(row) != 2:
            raise InputError('definition pair')
        definitions.append((text(row[0], 32), text(row[1], MAX_EXPRESSION)))
    try:
        context = Context(definitions, seed)
    except (ExpressionError, ValueError) as exc:
        raise InputError('definitions') from exc

    timeout = integer(document['timeout_ms'], 1, 10 ** 9)
    budgets = Budgets()

    raw_cases = sequence(document['cases'], MAX_CASES)
    budgets.take_items(0)
    case_names = set()
    cases = []
    for index, raw_case in enumerate(raw_cases):
        exact(raw_case, ('name', 'frames', 'expect'))
        label = name(raw_case['name'])
        if label in case_names:
            raise InputError('duplicate case name')
        case_names.add(label)
        frames = sequence(raw_case['frames'], MAX_ITEMS)
        budgets.take_items(len(frames))
        pauses = 0
        for position, frame in enumerate(frames):
            compile_frame(frame, context, 'case/%d/frame/%d' % (index, position),
                          budgets)
            if type(frame) is dict and frame.get('Type') == 'sleep':
                pauses += frame['Time_to_Stop']
        if pauses + timeout > MAX:
            raise InputError('case time overflow')
        cases.append({'name': label, 'frames': frames,
                      'expect': compile_expect(raw_case['expect'])})

    raw_events = sequence(document['events'], MAX_ITEMS)
    budgets.take_items(len(raw_events))
    events = []
    for index, raw_event in enumerate(raw_events):
        if type(raw_event) is not dict:
            raise InputError('event')
        kind = raw_event.get('kind')
        if type(kind) is not str:
            raise InputError('event kind')
        if kind == 'close':
            exact(raw_event, ('at', 'kind'))
            events.append(ExternalEvent(at=integer(raw_event['at']), kind='close'))
            continue
        if kind not in ('headers', 'data'):
            raise InputError('event kind')
        payload_key = 'fields' if kind == 'headers' else 'data'
        exact(raw_event, ('at', 'kind', 'stream', 'end', payload_key))
        at = integer(raw_event['at'])
        stream = integer(raw_event['stream'], 0, MAX_STREAM)
        end = raw_event['end']
        if type(end) is not bool:
            raise InputError('event end')
        if kind == 'headers':
            raw_fields = raw_event['fields']
            if type(raw_fields) is not list or len(raw_fields) > MAX_BLOCK_PAIRS:
                raise InputError('event fields')
            budgets.take_pairs(len(raw_fields))
            fields = []
            for position, pair in enumerate(raw_fields):
                if type(pair) is not list or len(pair) != 2:
                    raise InputError('event field pair')
                key = text(pair[0])
                value = text(pair[1])
                fields.append((
                    context.template(key, 'event/%d/h/%d/n' % (index, position)),
                    context.template(value, 'event/%d/h/%d/v' % (index, position)),
                ))
            events.append(ExternalEvent(at=at, kind=kind, stream=stream,
                                        fields=fields, end=end))
        else:
            data = context.template(text(raw_event['data']),
                                    'event/%d/data' % index)
            events.append(ExternalEvent(at=at, kind=kind, stream=stream,
                                        data=data, end=end))

    raw_channels = sequence(document['channels'], MAX_CHANNELS)
    channel_names = set()
    channels = []
    for index, raw_channel in enumerate(raw_channels):
        exact(raw_channel, ('name', 'parts'))
        label = name(raw_channel['name'])
        if label in channel_names:
            raise InputError('duplicate channel name')
        channel_names.add(label)
        raw_parts = sequence(raw_channel['parts'], MAX_ITEMS)
        budgets.take_items(len(raw_parts))
        parts = []
        for position, raw_part in enumerate(raw_parts):
            exact(raw_part, ('case', 'data'))
            owner = raw_part['case']
            if owner is not None:
                if type(owner) is not str or owner not in case_names:
                    raise InputError('owner label')
            data = context.template(
                text(raw_part['data']),
                'channel/%d/part/%d/data' % (index, position))
            parts.append((owner, data))
        channels.append({'name': label, 'parts': parts})

    return Compiled(context, timeout, cases, events, channels)


def run(document):
    compiled = compile_document(document)
    payload = compile_cases(compiled.cases, compiled.context)
    results = FuzzExecutor().send_payload(payload, compiled.events,
                                          compiled.timeout)
    expects = {case.name: {'method': case.expect.method,
                           'target': case.expect.target,
                           'host_folded': case.expect.host_folded}
               for case in payload.cases}
    sent_frames = {row['name']: row['request_frames'] for row in results}
    channels, origin = audit_channels(compiled.channels, expects, sent_frames)
    for row in results:
        state = origin[row['name']]
        row['origin_count'] = state['count']
        row['flags'] = case_flags(state, row['request_frames'])
    return {'cases': results, 'channels': channels}


def emit(result):
    encoded = json.dumps(result, ensure_ascii=True, separators=(',', ':'),
                         allow_nan=False).encode('ascii')
    stream = sys.stdout.buffer
    stream.write(encoded)
    stream.write(b'\n')
    stream.flush()


def main():
    gc.disable()
    try:
        raw = sys.stdin.buffer.read(MAX_STDIN + 1)
        if len(raw) > MAX_STDIN:
            raise InputError('input bytes')
        document = json.loads(raw.decode('utf8'), object_pairs_hook=pairs,
                              parse_constant=bad_constant,
                              parse_float=finite_float)
        result = run(document)
    except Exception:                            # noqa: BLE001 - contract
        if os.environ.get('H3ACT_DEBUG'):
            traceback.print_exc()
        result = {'error': 'input'}
    try:
        emit(result)
    except Exception:                            # noqa: BLE001 - last resort
        try:
            sys.stdout.buffer.write(b'{"error":"input"}\n')
            sys.stdout.buffer.flush()
        except Exception:
            os._exit(0)
    sys.exit(0)


if __name__ == '__main__':
    main()
PYEOF
